/* Beta 1.337 — DVL Theme Studio (UI + rotação dos 12 fundos do pacote enviado). Consome DVL_THEME_PRESETS/APPLY do
   boot no <head>. Painel de Aparência: 3 temas globais (Teal/Ocean/Carbon) +
   camada de fundo cinematográfico com controles (opacidade/escurecimento/nitidez/
   saturação/contraste/posição). Persiste em localStorage e restaura antes do paint
   (o boot já aplicou os tokens). As 12 imagens do pacote estão incorporadas no HTML para funcionamento offline. */
(function(){
  "use strict";
  if(window.__DVL_THEME_STUDIO_ON) return; window.__DVL_THEME_STUDIO_ON=true;
  var LS="dvl.themeStudio.v1";
  /* slots pras fotos reais (WebP data URI). Vazio por ora → placeholder. */
  window.DVL_THEME_BG_IMAGES = {"pack01":"data:image/webp;base64,","pack02":"data:image/webp;base64,","pack03":"data:image/webp;base64,","pack04":"data:image/webp;base64,","pack05":"data:image/webp;base64,","pack06":"data:image/webp;base64,","pack07":"data:image/webp;base64,","pack08":"data:image/webp;base64,","pack09":"data:image/webp;base64,","pack10":"data:image/webp;base64,","pack11":"data:image/webp;base64,","pack12":"data:image/webp;base64,"};
  var ORIGINAL_AUTO=[
    {id:"pack01",title:"F1 Neon \u00b7 Cidade 1",position:"50% 50%"},
    {id:"pack02",title:"F1 Neon \u00b7 Cidade 2",position:"50% 50%"},
    {id:"pack03",title:"F1 Neon \u00b7 Pista",position:"50% 50%"},
    {id:"pack04",title:"Cyber Skyline",position:"50% 50%"},
    {id:"pack05",title:"Corrida Chuvosa",position:"50% 50%"},
    {id:"pack06",title:"Paisagem Neon Chuvosa",position:"50% 50%"},
    {id:"pack07",title:"Estrada Molhada",position:"50% 50%"},
    {id:"pack08",title:"Noite Chuvosa",position:"50% 50%"},
    {id:"pack09",title:"Tempestade Cibern\u00e9tica",position:"50% 50%"},
    {id:"pack10",title:"Litoral Futurista",position:"50% 50%"},
    {id:"pack11",title:"Cidade Distante",position:"50% 50%"},
    {id:"pack12",title:"Estrada e Cidade",position:"50% 50%"}
  ];
  var AUTO_BG_MS=5*60*1000; // troca sincronizada a cada 5 minutos
  var SCENARIOS=[["originalAuto","Fundos Auto \u00b7 5 min"],["pack01","F1 Neon \u00b7 Cidade 1"],["pack02","F1 Neon \u00b7 Cidade 2"],["pack03","F1 Neon \u00b7 Pista"],["pack04","Cyber Skyline"],["pack05","Corrida Chuvosa"],["pack06","Paisagem Neon Chuvosa"],["pack07","Estrada Molhada"],["pack08","Noite Chuvosa"],["pack09","Tempestade Cibern\u00e9tica"],["pack10","Litoral Futurista"],["pack11","Cidade Distante"],["pack12","Estrada e Cidade"]];

  var DEF={ themeId:"teal", backgroundEnabled:true, backgroundId:"originalAuto", backgroundOpacity:0.10, backgroundDim:0.62, backgroundBlur:0.4, backgroundSaturation:0.72, backgroundContrast:1.04, backgroundPosition:"auto", __backgroundPack1337:1 };
  function load(){
    var out;
    try{ out=Object.assign({},DEF,JSON.parse(localStorage.getItem(LS)||"{}")); }catch(_){ out=Object.assign({},DEF); }
    /* Migra qualquer cenário antigo/removido para a rotação
       do novo pacote de 12 fundos, sem alterar os ajustes visuais do usuário. */
    var validBg={originalAuto:1,pack01:1,pack02:1,pack03:1,pack04:1,pack05:1,pack06:1,pack07:1,pack08:1,pack09:1,pack10:1,pack11:1,pack12:1};
    if(!validBg[out.backgroundId] || out.backgroundId==="christianAuto") out.backgroundId="originalAuto";
    delete out.__christianAuto1301; delete out.__originalAuto1331;
    out.__backgroundPack1337=1;
    try{localStorage.setItem(LS,JSON.stringify(out));}catch(_){}
    return out;
  }
  var cfg=load();
  function clone(o){ try{ return JSON.parse(JSON.stringify(o)); }catch(_){ return Object.assign({},o); } }
  var applied=clone(cfg);                       // último estado COMMITADO (o que está salvo)
  function dirty(){ return JSON.stringify(cfg)!==JSON.stringify(applied); }
  var _saveT=0; function persist(){ var now=Date.now(); if(now-_saveT<250){ clearTimeout(persist._t); persist._t=setTimeout(persist,260); return; } _saveT=now; try{ localStorage.setItem(LS, JSON.stringify(cfg)); }catch(_){} }

  /* ── camada de fundo (OVERLAY por cima, baixa opacidade) ──
     O gráfico se limpa pintando o próprio fundo opaco a cada frame, então não dá pra
     deixá-lo translúcido (rastro). Em vez disso a foto entra numa CAMADA FIXA POR CIMA
     de tudo, em opacidade baixa (6–14%, como o README pede) e pointer-events:none — dá a
     textura cinematográfica sobre o app inteiro (gráfico incluso) sem tocar no desenho.
     z-index alto o suficiente pra ficar sobre o gráfico, mas abaixo de modais/painéis. */
  var _bgFace=0,_bgSignature="",_autoTimer=0;
  function ensureBgLayer(){
    var el=document.getElementById("dvlThemeBg");
    if(!el){el=document.createElement("div");el.id="dvlThemeBg";
      el.style.cssText="position:fixed;inset:0;z-index:60;pointer-events:none;overflow:hidden;opacity:0;transition:opacity .35s ease";
      var common="position:absolute;inset:0;background-size:cover;background-repeat:no-repeat;opacity:0;transition:opacity 1800ms ease;will-change:opacity;";
      el.innerHTML='<div id="dvlThemeBgImg" style="'+common+'"></div><div id="dvlThemeBgImg2" style="'+common+'"></div>';
      document.body.appendChild(el);
    }else el.style.zIndex="60";
    return el;
  }
  function autoSlot(at){return Math.floor((at==null?Date.now():at)/AUTO_BG_MS);}
  function autoItem(at){return ORIGINAL_AUTO[((autoSlot(at)%ORIGINAL_AUTO.length)+ORIGINAL_AUTO.length)%ORIGINAL_AUTO.length];}
  function effectivePosition(item){var p=cfg.backgroundPosition||"auto";return p==="auto"?(item&&item.position?item.position:"50% 50%"):p;}
  function resolvedBackground(){
    if(cfg.backgroundId==="originalAuto"){var item=autoItem();return{id:item.id,title:item.title,src:window.DVL_THEME_BG_IMAGES[item.id]||"",position:effectivePosition(item),auto:true};}
    return{id:cfg.backgroundId,title:cfg.backgroundId,src:window.DVL_THEME_BG_IMAGES[cfg.backgroundId]||"",position:effectivePosition(null),auto:false};
  }
  function filterValue(){return"blur("+(cfg.backgroundBlur||0)+"px) saturate("+Math.round((cfg.backgroundSaturation||.62)*100)+"%) contrast("+Math.round((cfg.backgroundContrast||1)*100)+"%)";}
  function preloadNext(){if(cfg.backgroundId!=="originalAuto")return;try{var cur=autoItem(),i=ORIGINAL_AUTO.indexOf(cur),nx=ORIGINAL_AUTO[(i+1)%ORIGINAL_AUTO.length],src=window.DVL_THEME_BG_IMAGES[nx.id];if(src){var im=new Image();im.decoding="async";im.src=src;}}catch(_){}}
  function scheduleAuto(){clearTimeout(_autoTimer);_autoTimer=0;if(!cfg.backgroundEnabled||cfg.backgroundId!=="originalAuto")return;var delay=AUTO_BG_MS-(Date.now()%AUTO_BG_MS)+90;_autoTimer=setTimeout(function(){if(!document.hidden)applyBackground(true);scheduleAuto();},delay);}
  function applyBackground(force){
    var el=ensureBgLayer(),a=document.getElementById("dvlThemeBgImg"),b=document.getElementById("dvlThemeBgImg2");
    if(!cfg.backgroundEnabled){el.style.opacity="0";document.documentElement.style.setProperty("--dvl-bg-photo","0");scheduleAuto();return;}
    var r=resolvedBackground(),th=window.DVL_THEME_PRESETS[cfg.themeId]||window.DVL_THEME_PRESETS.teal,tk=th.tokens||{};
    var bg=r.src?"url('"+r.src+"')":"radial-gradient(1200px 700px at 50% -10%, #14d8a022, transparent 60%), linear-gradient(180deg,"+(tk["--bg1"]||"#08141d")+","+(tk["--bg0"]||"#061017")+")";
    var sig=r.id+"|"+r.position+"|"+(r.src?"img":"fallback");
    [a,b].forEach(function(layer){if(layer){layer.style.backgroundPosition=r.position;layer.style.filter=filterValue();}});
    if(force||sig!==_bgSignature){
      var incoming=_bgFace?a:b,outgoing=_bgFace?b:a;_bgFace=_bgFace?0:1;
      incoming.style.transition="none";incoming.style.opacity="0";incoming.style.backgroundImage=bg;incoming.style.backgroundPosition=r.position;incoming.style.filter=filterValue();void incoming.offsetWidth;
      incoming.style.transition="opacity 1800ms ease";requestAnimationFrame(function(){incoming.style.opacity="1";if(outgoing)outgoing.style.opacity="0";});_bgSignature=sig;
    }
    var op=cfg.backgroundOpacity!=null?cfg.backgroundOpacity:.10,dimK=1-.5*(cfg.backgroundDim!=null?cfg.backgroundDim:.62);
    el.style.opacity=String(Math.max(0,Math.min(.4,op*dimK*1.6)));document.documentElement.style.setProperty("--dvl-bg-photo","1");
    window.__DVL_THEME_BG_CURRENT={id:r.id,title:r.title,slot:autoSlot(),nextAt:(autoSlot()+1)*AUTO_BG_MS};preloadNext();scheduleAuto();
  }

  /* ── API ──
     Modelo com "Aplicar": mexer nos controles só PRÉ-VISUALIZA (aplica os tokens/fundo
     na hora, mas NÃO salva). Só o botão Aplicar comita (persist + vira o estado salvo).
     Fechar o painel sem aplicar reverte a pré-visualização pro último estado salvo. */
  function previewTheme(id){ if(!window.DVL_THEME_PRESETS[id]) return; cfg.themeId=id; try{ window.DVL_THEME_APPLY_TOKENS(id); }catch(_){}
    applyBackground();
    /* avisa o gráfico/overlays pra repintarem com os novos neutros (sem resetar zoom) */
    try{ if(typeof drawSoon==="function") drawSoon(); }catch(_){}
    try{ window.dispatchEvent(new CustomEvent("dvl:theme-change",{detail:{themeId:id}})); }catch(_){}
  }
  function commit(){ persist(); applied=clone(cfg); refreshApply();
    try{ window.dispatchEvent(new CustomEvent("dvl:theme-apply",{detail:clone(cfg)})); }catch(_){}
  }
  function revert(){ cfg=clone(applied); try{ window.DVL_THEME_APPLY_TOKENS(cfg.themeId); }catch(_){} applyBackground();
    try{ if(typeof drawSoon==="function") drawSoon(); }catch(_){} }
  /* público: aplica E salva de imediato (uso programático) */
  function applyTheme(id){ previewTheme(id); commit(); }
  window.DVLThemeStudio={ applyTheme:applyTheme, applyBackground:applyBackground, getConfig:function(){return Object.assign({},applied);},
    setBackground:function(patch){ Object.assign(cfg, patch||{}); applyBackground(); commit(); },
    getCurrentBackground:function(){return Object.assign({},window.__DVL_THEME_BG_CURRENT||{});},
    reset:function(){ cfg=Object.assign({}, DEF); try{ window.DVL_THEME_APPLY_TOKENS(cfg.themeId); }catch(_){} applyBackground(); commit(); renderPanel(); } };

  /* ── painel Theme Studio ── */
  var panel=null;
  function chip(label,active,attr){ return '<button type="button" '+attr+' style="flex:0 0 auto;padding:6px 12px;border-radius:8px;border:1px solid '+(active?"var(--accent,#14d8a0)":"rgba(142,174,190,.22)")+';background:'+(active?"rgba(20,216,160,.14)":"rgba(142,174,190,.06)")+';color:'+(active?"#eafff4":"#bcd3e2")+';font:800 12px system-ui;cursor:pointer">'+label+'</button>'; }
  function slider(id,label,min,max,step,val,unit){ return '<div style="margin:7px 0"><div style="display:flex;justify-content:space-between;font-size:11px;color:#9fb3c8;margin-bottom:3px"><span>'+label+'</span><b style="color:#dcebe4" id="'+id+'Val">'+val+(unit||"")+'</b></div><input id="'+id+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+val+'" style="width:100%"></div>'; }

  function bodyHTML(){
    var themeCards=Object.keys(window.DVL_THEME_PRESETS).map(function(id){ var pr=window.DVL_THEME_PRESETS[id]; var on=cfg.themeId===id;
      var sw=(pr.swatch||[]).map(function(c){return '<span style="width:16px;height:16px;border-radius:5px;background:'+c+';display:inline-block"></span>';}).join("");
      return '<button type="button" data-dvl-theme="'+id+'" style="flex:1;min-width:96px;padding:10px;border-radius:12px;border:1.5px solid '+(on?"var(--accent,#14d8a0)":"rgba(142,174,190,.2)")+';background:rgba(142,174,190,.05);cursor:pointer;text-align:left"><div style="display:flex;gap:4px;margin-bottom:6px">'+sw+'</div><b style="color:#eafff4;font-size:12px">'+pr.name+'</b>'+(on?'<span style="color:var(--accent,#14d8a0);font-size:10px;display:block">● ativo</span>':'')+'</button>';
    }).join("");
    var scen=SCENARIOS.map(function(s){ return chip(s[1], cfg.backgroundId===s[0], 'data-dvl-bg-scen="'+s[0]+'"'); }).join("");
    var pos=[["auto","Auto"],["center","Centro"],["top","Topo"],["bottom","Base"]].map(function(p){ return chip(p[1], cfg.backgroundPosition===p[0], 'data-dvl-bg-pos="'+p[0]+'"'); }).join("");
    var noImg = cfg.backgroundId==="originalAuto" ? !ORIGINAL_AUTO.some(function(x){return !!window.DVL_THEME_BG_IMAGES[x.id];}) : !(window.DVL_THEME_BG_IMAGES[cfg.backgroundId]);
    return '<div class="dvl-vt-section"><div class="dvl-vt-section-title"><span>Tema de cores</span></div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 2px">'+themeCards+'</div>'
      +'<div style="font-size:10.5px;color:#8ea0af;margin-top:4px">Troca o app inteiro (fundo, painéis, textos, bordas, acentos). Compra/venda, TP/SL e velas mantêm o significado.</div></div>'
      +'<div class="dvl-vt-section"><div class="dvl-vt-section-title"><span>Plano de fundo do gráfico</span></div>'
      +'<div class="dvl-vt-field"><label>Ativar fundo</label><label class="dvl-switch"><input id="dvlBgOn" type="checkbox" '+(cfg.backgroundEnabled?"checked":"")+'><i></i><b></b></label></div>'
      +'<div style="font-size:10px;color:#7f9c8e;margin:2px 0 6px">Cenário</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px">'+scen+'</div>'
      +(cfg.backgroundId==="originalAuto"?'<div style="font-size:10.5px;color:#bcd3e2;background:rgba(20,216,160,.07);border:1px solid rgba(20,216,160,.20);border-radius:8px;padding:7px 9px;margin-bottom:8px"><b style="color:#83f2ca">Rotação automática</b> · alterna os 12 fundos do novo pacote a cada 5 minutos, com crossfade e pré-carregamento.</div>':'')
      +(noImg?'<div style="font-size:10.5px;color:#f4b942;background:rgba(244,185,66,.08);border:1px solid rgba(244,185,66,.22);border-radius:8px;padding:7px 9px;margin-bottom:8px">Sem imagem pra este cenário ainda — mostrando um véu na cor do tema. Me envie as fotos (WebP 1920×1080, ~180–350 KB) que eu embuto e este aviso some.</div>':'')
      +slider("dvlBgOpacity","Opacidade",0,20,1,Math.round((cfg.backgroundOpacity||0)*100),"%")
      +slider("dvlBgDim","Escurecimento",30,90,1,Math.round((cfg.backgroundDim||0)*100),"%")
      +slider("dvlBgBlur","Nitidez (blur)",0,4,0.1,(cfg.backgroundBlur||0),"px")
      +slider("dvlBgSat","Saturação",35,100,1,Math.round((cfg.backgroundSaturation||0)*100),"%")
      +slider("dvlBgContrast","Contraste",80,125,1,Math.round((cfg.backgroundContrast||1)*100),"%")
      +'<div style="font-size:10px;color:#7f9c8e;margin:6px 0 4px">Posição</div><div style="display:flex;gap:6px;flex-wrap:wrap">'+pos+'</div>'
      +'</div>';
  }
  function renderPanel(){ if(!panel) return; var b=panel.querySelector("#dvlThemeBody"); if(b){ b.innerHTML=bodyHTML(); bind(b); } }
  function bind(b){
    b.querySelectorAll("[data-dvl-theme]").forEach(function(el){ el.addEventListener("click",function(){ previewTheme(el.getAttribute("data-dvl-theme")); renderPanel(); refreshApply(); }); });
    b.querySelectorAll("[data-dvl-bg-scen]").forEach(function(el){ el.addEventListener("click",function(){ cfg.backgroundId=el.getAttribute("data-dvl-bg-scen"); applyBackground(); renderPanel(); refreshApply(); }); });
    b.querySelectorAll("[data-dvl-bg-pos]").forEach(function(el){ el.addEventListener("click",function(){ cfg.backgroundPosition=el.getAttribute("data-dvl-bg-pos"); applyBackground(); renderPanel(); refreshApply(); }); });
    var on=b.querySelector("#dvlBgOn"); if(on) on.addEventListener("change",function(){ cfg.backgroundEnabled=on.checked; applyBackground(); renderPanel(); refreshApply(); });
    function sl(id,key,scale,unit){ var el=b.querySelector("#"+id); if(!el) return; el.addEventListener("input",function(){ var v=Number(el.value); cfg[key]=scale?v/scale:v; var lab=b.querySelector("#"+id+"Val"); if(lab) lab.textContent=(scale?Math.round(v):v)+(unit||""); refreshApply(); requestAnimationFrame(applyBackground); }); }
    sl("dvlBgOpacity","backgroundOpacity",100,"%"); sl("dvlBgDim","backgroundDim",100,"%"); sl("dvlBgBlur","backgroundBlur",0,"px"); sl("dvlBgSat","backgroundSaturation",100,"%"); sl("dvlBgContrast","backgroundContrast",100,"%");
  }
  /* botão Aplicar (rodapé): reflete se há alterações pendentes */
  function refreshApply(){ if(!panel) return; var btn=panel.querySelector("#dvlThemeApply"), hint=panel.querySelector("#dvlThemeApplyHint"); if(!btn) return;
    var d=dirty(); btn.disabled=!d; btn.style.opacity=d?"1":".45"; btn.style.cursor=d?"pointer":"default"; btn.textContent=d?"Aplicar":"Aplicado ✓";
    if(hint) hint.textContent=d?"Alterações não aplicadas — clique em Aplicar":"Tudo aplicado";
  }
  function openPanel(){
    if(!panel){ panel=document.createElement("div"); panel.id="dvlThemeStudioPanel"; panel.className="dvl-vt-panel";
      panel.innerHTML='<div class="dvl-vt-head"><div class="dvl-vt-title"><b>Aparência · Theme Studio</b><small>tema global + fundo</small></div><div class="dvl-vt-head-actions"><button class="dvl-vt-close" id="dvlThemeReset" type="button" title="Restaurar padrão" style="font-size:15px">⟲</button><button class="dvl-vt-close" id="dvlThemeClose" type="button">×</button></div></div><div class="dvl-vt-body" id="dvlThemeBody"></div>'
        +'<div class="dvl-vt-foot"><div style="flex:1;min-width:0"><div style="font-size:11px;font-weight:900;color:#dcebe4">Pré-visualização ao vivo</div><div id="dvlThemeApplyHint" style="font-size:10px;color:#8ea0af">Tudo aplicado</div></div>'
        +'<button id="dvlThemeApply" type="button" style="flex:0 0 auto;padding:10px 22px;border-radius:11px;border:1px solid var(--accent,#14d8a0);background:var(--accent,#14d8a0);color:#04120c;font:900 13px system-ui;cursor:default;opacity:.45">Aplicado ✓</button></div>';
      document.body.appendChild(panel);
      panel.addEventListener("pointerdown",function(e){ e.stopPropagation(); },true);
      panel.querySelector("#dvlThemeClose").addEventListener("click",function(){ if(dirty()){ revert(); renderPanel(); refreshApply(); } panel.classList.remove("is-open"); });
      panel.querySelector("#dvlThemeReset").addEventListener("click",function(){ window.DVLThemeStudio.reset(); });
      panel.querySelector("#dvlThemeApply").addEventListener("click",function(){ if(!dirty()) return; commit(); });
    }
    renderPanel(); refreshApply(); panel.classList.add("is-open");
  }
  window.DVLThemeStudio.open=openPanel;

  /* launcher no header (ao lado do ⚙) */
  function addLauncher(){
    var gear=document.getElementById("dvl1b_settingsBtn"); if(!gear||document.getElementById("dvlThemeLauncher")) return;
    var btn=gear.cloneNode(false); btn.id="dvlThemeLauncher"; btn.removeAttribute("onclick");
    btn.innerHTML='🎨'; btn.title="Theme Studio"; btn.style.cursor="pointer";
    btn.addEventListener("click",function(ev){ ev.stopPropagation(); openPanel(); });
    if(gear.parentNode) gear.parentNode.insertBefore(btn, gear);
  }

  function boot(){ applyBackground(); addLauncher(); setInterval(addLauncher, 3000);
    try{ window.addEventListener("dvl:theme-change",function(){ applyBackground(); }); }catch(_){}
    try{ document.addEventListener("visibilitychange",function(){if(!document.hidden)applyBackground(true);else clearTimeout(_autoTimer);}); }catch(_){}
    scheduleAuto();
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",boot,{once:true}); else boot();
})();
